(4929523, 717606, 64670, '<td valign="top">This image is very noisy and lacks a crisp focus point.</td>', 'This image is very noisy and lacks a crisp focus point.', '2008-09-03 01:10:49.000000', NULL, 1),
(4929527, 715807, 80807, '<td valign="top">Humor always ups the score. Homers face is a bit shadowy.</td>', 'Humor always ups the score. Homers face is a bit shadowy.', '2008-09-03 01:11:51.000000', NULL, 1),
(4929541, 717586, 64670, '<td valign="top">Lovely subject, love the ''fill the frame''.  However the image is incredibly dark - not sure if that was your intention, but on my screen it really detracts from the viewing pleasure.</td>', 'Lovely subject, love the ''fill the frame''.  However the image is incredibly dark - not sure if that was your intention, but on my screen it really detracts from the viewing pleasure.', '2008-09-03 01:13:06.000000', NULL, 1),
(4929546, 717524, 80807, '<td valign="top">Nice idea. I would have scored it higher if the "falls" were either better focused or did not take up so much foreground space.</td>', 'Nice idea. I would have scored it higher if the "falls" were either better focused or did not take up so much foreground space.', '2008-09-03 01:13:49.000000', NULL, 1),
(4929558, 716006, 80807, '<td valign="top">Good color and light.  Overall pose is neutral.</td>', 'Good color and light.  Overall pose is neutral.', '2008-09-03 01:15:40.000000', NULL, 1),
