(4929818, 714931, 97225, '<td valign="top">That''s a pretty cute nativity scene.</td>', 'That''s a pretty cute nativity scene.', '2008-09-03 02:01:54.000000', NULL, 1),
(4929832, 717268, 97225, '<td valign="top">I think I would like it better if the teddies were a bit closer, using up more of that foreground. The big bear could be free of the busy background behind him.</td>', 'I think I would like it better if the teddies were a bit closer, using up more of that foreground. The big bear could be free of the busy background behind him.', '2008-09-03 02:06:00.000000', NULL, 1),
