(4930018, 715732, 97225, '<td valign="top">She''s a little cutie isn''t she?</td>', 'She''s a little cutie isn''t she?', '2008-09-03 02:51:29.000000', NULL, 1),
(4930020, 716755, 97936, '<td valign="top">Obviously, this is a very cool photo.  To me, personally, it seems unnatural to have the doll held with this hand and the thumb facing away, so I''d like to swap arms.  However, the direction of the light and the proportion of the image is excellent.</td>', 'Obviously, this is a very cool photo.  To me, personally, it seems unnatural to have the doll held with this hand and the thumb facing away, so I''d like to swap arms.  However, the direction of the light and the proportion of the image is excellent.', '2008-09-03 02:52:04.000000', NULL, 1),
(4930028, 715173, 97225, '<td valign="top">Boy, this brings back memories. My daughter loved (to bits) her Raggedy Ann about 33 years ago. I think she was identical to this one, right down to the dress.Then of course she went through the cabbage patch kid phase too. I was going to use them for my entry but couldn''t find them. I''ll have to quiz my granddaughters.I have to give you a good score for nostalgia.(I like your photo too.)</td>', 'Boy, this brings back memories. My daughter loved (to bits) her Raggedy Ann about 33 years ago. I think she was identical to this one, right down to the dress.Then of course she went through the cabbage patch kid phase too. I was going to use them for my entry but couldn''t find them. I''ll have to quiz my granddaughters.I have to give you a good score for nostalgia.(I like your photo too.)', '2008-09-03 02:57:39.000000', NULL, 1),
(4930029, 716233, 25166, '<td valign="top">I spy with my little eye, something that looks like a dq! Bad luck.</td>', 'I spy with my little eye, something that looks like a dq! Bad luck.', '2008-09-03 02:57:46.000000', NULL, 1),
(4930033, 717664, 97225, '<td valign="top">She is a beauty, isn''t she?</td>', 'She is a beauty, isn''t she?', '2008-09-03 02:59:08.000000', NULL, 1),
(4930035, 717720, 97225, '<td valign="top">Nice and clear and well lit.</td>', 'Nice and clear and well lit.', '2008-09-03 03:00:29.000000', NULL, 1),
