(4930063, 717619, 97225, '<td valign="top">That''s a goodie.( I just put some snail bait out!)</td>', 'That''s a goodie.( I just put some snail bait out!)', '2008-09-03 03:13:56.000000', NULL, 1),
(4930064, 716894, 97936, '<td valign="top">The monster is cute, but I think he gets very lost in the other textured browns.  I think the extreme brightness of the shovel and bucket really compound this issue and make me unsure of where to look in the photo.  I like how you''ve attempted to capture the puppet''s character by incorporating other props, but I think the photo would be better if there was less competition with the textured fur OR if there were not other bright spots so that attention could be drawn to the puppet''s eyes.</td>', 'The monster is cute, but I think he gets very lost in the other textured browns.  I think the extreme brightness of the shovel and bucket really compound this issue and make me unsure of where to look in the photo.  I like how you''ve attempted to capture the puppet''s character by incorporating other props, but I think the photo would be better if there was less competition with the textured fur OR if there were not other bright spots so that attention could be drawn to the puppet''s eyes.', '2008-09-03 03:14:40.000000', NULL, 1),
(4930065, 717723, 97225, '<td valign="top">Cute. I like the contrast with the black.</td>', 'Cute. I like the contrast with the black.', '2008-09-03 03:14:53.000000', NULL, 1),
(4930066, 717590, 97225, '<td valign="top">That might be a stretch.</td>', 'That might be a stretch.', '2008-09-03 03:15:33.000000', NULL, 1),
(4930067, 717517, 97225, '<td valign="top">Ther is certainly some eye-contact there.</td>', 'Ther is certainly some eye-contact there.', '2008-09-03 03:16:27.000000', NULL, 1),
(4930069, 717524, 97225, '<td valign="top">That would have been a great shot if you had got a sharper focus on the figure.</td>', 'That would have been a great shot if you had got a sharper focus on the figure.', '2008-09-03 03:17:23.000000', NULL, 1),
