(4931800, 717586, 97936, '<td valign="top">I think this is a bit too dark, but the framing is quite nice.</td>', 'I think this is a bit too dark, but the framing is quite nice.', '2008-09-03 16:20:45.000000', NULL, 1),
(4931804, 716715, 97936, '<td valign="top">I like how you''ve chosen to focus on the second doll instead of the one in front.  I would like it better if this doll''s dress were not quite as crazy.  I would rather the focus be her face, and I find the pattern very distracting.</td>', 'I like how you''ve chosen to focus on the second doll instead of the one in front.  I would like it better if this doll''s dress were not quite as crazy.  I would rather the focus be her face, and I find the pattern very distracting.', '2008-09-03 16:22:19.000000', NULL, 1),
(4931811, 717502, 97936, '<td valign="top">I think a shallower depth of field would be nice.  The textures of the rock are very strong, and if the background were even more blurred, I think it would help emphasize the doll more.</td>', 'I think a shallower depth of field would be nice.  The textures of the rock are very strong, and if the background were even more blurred, I think it would help emphasize the doll more.', '2008-09-03 16:25:12.000000', NULL, 1),
