(4931850, 717364, 97166, '<td valign="top">Some fill light would have been a real bonus here.</td>', 'Some fill light would have been a real bonus here.', '2008-09-03 16:38:20.000000', NULL, 1),
(4931856, 717742, 97166, '<td valign="top">Shock value rarely works here.</td>', 'Shock value rarely works here.', '2008-09-03 16:42:52.000000', NULL, 1),
(4931857, 717734, 97166, '<td valign="top">ok, I admit it, I laughed.</td>', 'ok, I admit it, I laughed.', '2008-09-03 16:43:30.000000', NULL, 1),
