INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4934814, 717619, 86848, '<td valign="top">Neat image, but I''m drawn more to the flower than to the puppets.  I think it not only competes, but wins for attention.  Focus on the puppets is off a little while the flowers focus is spot on making the flower even more the center of attention.<br/> <br/>Just my opinion!  :)</td>', 'Neat image, but I''m drawn more to the flower than to the puppets.  I think it not only competes, but wins for attention.  Focus on the puppets is off a little while the flowers focus is spot on making the flower even more the center of attention. Just my opinion!  :)', '2008-09-04 18:55:05.000000', NULL, 1),
(4934816, 717515, 97853, '<td valign="top">This is a little spooky...</td>', 'This is a little spooky...', '2008-09-04 18:56:34.000000', NULL, 1),
(4934818, 717734, 86848, '<td valign="top">OMG, it took a second to realize what I was looking at, but thats funny!  Good focus AND bokeh.  Nice idea!</td>', 'OMG, it took a second to realize what I was looking at, but thats funny!  Good focus AND bokeh.  Nice idea!', '2008-09-04 18:57:08.000000', NULL, 1),
(4934824, 717273, 86848, '<td valign="top">Cute idea, but I think the shadows on the doll kind of take away from the overall appearance of the shot.  Kind of makes it look dirty.  The DOF is a little awkward for me.  I think it would look better with either a sharper background or blurred out, but it makes me feel like I need to put on my glasses.  :)<br/> <br/>Just my opinion!  :)</td>', 'Cute idea, but I think the shadows on the doll kind of take away from the overall appearance of the shot.  Kind of makes it look dirty.  The DOF is a little awkward for me.  I think it would look better with either a sharper background or blurred out, but it makes me feel like I need to put on my glasses.  :) Just my opinion!  :)', '2008-09-04 19:02:34.000000', NULL, 1),
(4934837, 716631, 86848, '<td valign="top">I like the shot although its a little dark and the midsection of the doll seems to lose some detail.  The shadow seems to compete with the doll just a little for attention.</td>', 'I like the shot although its a little dark and the midsection of the doll seems to lose some detail.  The shadow seems to compete with the doll just a little for attention.', '2008-09-04 19:04:59.000000', NULL, 1),
(4934842, 715496, 86848, '<td valign="top">Funny, although the highlight running the length of the leg is distracting, might have been better with softer lighting.<br/> <br/>Just my opinion! :)</td>', 'Funny, although the highlight running the length of the leg is distracting, might have been better with softer lighting. Just my opinion! :)', '2008-09-04 19:07:38.000000', NULL, 1),
(4934847, 714739, 86848, '<td valign="top">Composition isn''t bad although I think the shot could be brighter to help bring attention to the subject.  Might have been better with the subject offset to one side more ( rule of thirds ).</td>', 'Composition isn''t bad although I think the shot could be brighter to help bring attention to the subject.  Might have been better with the subject offset to one side more ( rule of thirds ).', '2008-09-04 19:11:05.000000', NULL, 1),
(4934850, 717586, 86848, '<td valign="top">Not bad, but DARK.  Could use a bit more brightness.  Its even hard to make out the color of the eyes on the doll.  Focus is good although DOF may be a little shallow with the necklace blurred out.<br/> <br/>Just my opinion!  :)</td>', 'Not bad, but DARK.  Could use a bit more brightness.  Its even hard to make out the color of the eyes on the doll.  Focus is good although DOF may be a little shallow with the necklace blurred out. Just my opinion!  :)', '2008-09-04 19:12:41.000000', NULL, 1),
(4934851, 717347, 86848, '<td valign="top">Hmm, makes you smile as soon as you see it. :)  Shot is a little dark overall and I think it might have been better without the wing clipped.<br/> <br/>JMO!  :)</td>', 'Hmm, makes you smile as soon as you see it. :)  Shot is a little dark overall and I think it might have been better without the wing clipped. JMO!  :)', '2008-09-04 19:14:19.000000', NULL, 1),
(4934853, 716354, 86848, '<td valign="top">Not a bad shot.  I like the idea for the background.  Really adds to the photo.</td>', 'Not a bad shot.  I like the idea for the background.  Really adds to the photo.', '2008-09-04 19:16:48.000000', NULL, 1),
(4934859, 716439, 86848, '<td valign="top">Nice bokeh, and it is somewhat lifelike.  Lighting is nice although I would like it a little brighter.</td>', 'Nice bokeh, and it is somewhat lifelike.  Lighting is nice although I would like it a little brighter.', '2008-09-04 19:18:32.000000', NULL, 1),
(4934862, 717499, 86848, '<td valign="top">Oh poor Dorothy!  :0  Has a definite age to it even beyond the hair missing.  Nice shot altogether.  Lighting is soft, which is good in my opinion, but I think it could be a touch brighter.</td>', 'Oh poor Dorothy!  :0  Has a definite age to it even beyond the hair missing.  Nice shot altogether.  Lighting is soft, which is good in my opinion, but I think it could be a touch brighter.', '2008-09-04 19:20:23.000000', NULL, 1),
(4934885, 714926, 94265, '<td valign="top">The lighting is kinda off on this, very dark in places.</td>', 'The lighting is kinda off on this, very dark in places.', '2008-09-04 19:38:56.000000', NULL, 1),
(4934887, 717740, 94265, '<td valign="top">Not sure I''m keen on this effect. Composition is Ok.</td>', 'Not sure I''m keen on this effect. Composition is Ok.', '2008-09-04 19:39:55.000000', NULL, 1),
(4934890, 715566, 94265, '<td valign="top">Kinda fuzzy looking, not very sharp. The light is a bit flat too.</td>', 'Kinda fuzzy looking, not very sharp. The light is a bit flat too.', '2008-09-04 19:40:54.000000', NULL, 1),
(4934892, 716612, 94265, '<td valign="top">Quite cute and nice colours, I''d have chosen a different crop though. The block-red background detracts a bit from the froggies.</td>', 'Quite cute and nice colours, I''d have chosen a different crop though. The block-red background detracts a bit from the froggies.', '2008-09-04 19:41:55.000000', NULL, 1),
(4934894, 717502, 94265, '<td valign="top">I don''t care for the idea much but the focus on the rock is quite good.</td>', 'I don''t care for the idea much but the focus on the rock is quite good.', '2008-09-04 19:42:27.000000', NULL, 1),
(4934897, 714739, 94265, '<td valign="top">A toy shot on top of an office computer seems to be very little effort, those lights behind him distract an awful lot too.</td>', 'A toy shot on top of an office computer seems to be very little effort, those lights behind him distract an awful lot too.', '2008-09-04 19:44:16.000000', NULL, 1),
(4934898, 717084, 94265, '<td valign="top">Too small, very grainy and poor lighting.</td>', 'Too small, very grainy and poor lighting.', '2008-09-04 19:44:52.000000', NULL, 1),
(4934899, 717590, 94265, '<td valign="top">Kites aren''t puppets of any sort to my mind, it''s a nice enough shot though.</td>', 'Kites aren''t puppets of any sort to my mind, it''s a nice enough shot though.', '2008-09-04 19:45:50.000000', NULL, 1),
(4934904, 715496, 94265, '<td valign="top">The light is quite harsh, especially on her face and right leg.</td>', 'The light is quite harsh, especially on her face and right leg.', '2008-09-04 19:47:12.000000', NULL, 1),
(4934906, 715173, 94265, '<td valign="top">I''m not too keen on that blade of grass obstructing the middle of the rag doll''s face. I like the crop though.</td>', 'I''m not too keen on that blade of grass obstructing the middle of the rag doll''s face. I like the crop though.', '2008-09-04 19:48:39.000000', NULL, 1),
(4934908, 716894, 94265, '<td valign="top">He looks shocked, must be a big spider on the sand pile.</td>', 'He looks shocked, must be a big spider on the sand pile.', '2008-09-04 19:49:51.000000', NULL, 1),
(4934909, 714782, 94265, '<td valign="top">I''d like just a little more focus on this, otherwise it looks good.</td>', 'I''d like just a little more focus on this, otherwise it looks good.', '2008-09-04 19:50:17.000000', NULL, 1),
(4934910, 717541, 94265, '<td valign="top">The light on the rock is a bit harsh, pulls my gaze down from the monkey.</td>', 'The light on the rock is a bit harsh, pulls my gaze down from the monkey.', '2008-09-04 19:51:56.000000', NULL, 1),
(4934911, 717573, 86848, '<td valign="top">Wow, I like how the blue eyes really pop out.  The mirror behind them adds a nice effect.  Lighting is pretty good. Overall, I like it.</td>', 'Wow, I like how the blue eyes really pop out.  The mirror behind them adds a nice effect.  Lighting is pretty good. Overall, I like it.', '2008-09-04 19:52:36.000000', NULL, 1),
(4934914, 717524, 94265, '<td valign="top">There''s so much DOF blur that the pic looks a bit hazy to me.</td>', 'There''s so much DOF blur that the pic looks a bit hazy to me.', '2008-09-04 19:54:09.000000', NULL, 1),
(4934918, 717663, 94265, '<td valign="top">Nice shot of the pier, I''d have laid the doll a little more centred or something though, so none of her was cropped out.</td>', 'Nice shot of the pier, I''d have laid the doll a little more centred or something though, so none of her was cropped out.', '2008-09-04 19:54:50.000000', NULL, 1),
(4934920, 716467, 86848, '<td valign="top">Nice idea with the mirrors.  Not a bad shot, but I think the lighting makes it look really flat.  Not much depth to the photo.  Focus seems a bit off.<br/> <br/>JMO!  :)</td>', 'Nice idea with the mirrors.  Not a bad shot, but I think the lighting makes it look really flat.  Not much depth to the photo.  Focus seems a bit off. JMO!  :)', '2008-09-04 19:55:15.000000', NULL, 1),
(4934921, 717608, 94265, '<td valign="top">Interesting take on the challenge.</td>', 'Interesting take on the challenge.', '2008-09-04 19:55:18.000000', NULL, 1),
(4934923, 717573, 94265, '<td valign="top">If they weren''t mirrored I''d like this a lot more. Their reflections back there make it a bit cluttered behind the doll. I''d like to see them more centred, with woody''s arm not cropped off.</td>', 'If they weren''t mirrored I''d like this a lot more. Their reflections back there make it a bit cluttered behind the doll. I''d like to see them more centred, with woody''s arm not cropped off.', '2008-09-04 19:57:22.000000', NULL, 1),
(4934925, 715807, 94265, '<td valign="top">Cute idea, the light is a bit dim though.</td>', 'Cute idea, the light is a bit dim though.', '2008-09-04 19:57:54.000000', NULL, 1),
(4934928, 717698, 94265, '<td valign="top">The grass seems a bit more in focus than she is. Her eyes stand out nicely though.</td>', 'The grass seems a bit more in focus than she is. Her eyes stand out nicely though.', '2008-09-04 19:58:20.000000', NULL, 1),
(4934929, 717112, 86848, '<td valign="top">--or-- I don''t think we''re in Kansas anymore Toto.  :)<br/> <br/>Good focus, but the lighting appears a little harsh, especially on the right side.  I''m not completely sure, but I think you can see the reflection of the camera in the alien things.<br/> <br/>JMO!  :)</td>', '--or-- I don''t think we''re in Kansas anymore Toto.  :) Good focus, but the lighting appears a little harsh, especially on the right side.  I''m not completely sure, but I think you can see the reflection of the camera in the alien things. JMO!  :)', '2008-09-04 19:58:43.000000', NULL, 1),
(4934931, 717594, 94265, '<td valign="top">Good shot, I''d have used a non-textured background though. The crop is good.</td>', 'Good shot, I''d have used a non-textured background though. The crop is good.', '2008-09-04 19:59:08.000000', NULL, 1),
(4934936, 717091, 86848, '<td valign="top">Hmm, focus looks a little off and lighting seems a bit high key and harsh.  Highlights on left side look blown out. Personally I think this could have been better in color.<br/> <br/>JMO  :)</td>', 'Hmm, focus looks a little off and lighting seems a bit high key and harsh.  Highlights on left side look blown out. Personally I think this could have been better in color. JMO  :)', '2008-09-04 20:04:16.000000', NULL, 1),
(4934937, 717724, 86848, '<td valign="top">Cute idea, and doll.  It almost appears that some of the lighting is blue from the left side?  Maybe WB was off a little?  I''m not sure.  Overall I think the lighting appears to flatten the image.<br/> <br/>JMO!  :)</td>', 'Cute idea, and doll.  It almost appears that some of the lighting is blue from the left side?  Maybe WB was off a little?  I''m not sure.  Overall I think the lighting appears to flatten the image. JMO!  :)', '2008-09-04 20:07:31.000000', NULL, 1),
(4934939, 717454, 86848, '<td valign="top">Wow, nice shallow DOF.  It pulls you right into the dolls eyes.  Lighting is nice and soft.  Good shot.</td>', 'Wow, nice shallow DOF.  It pulls you right into the dolls eyes.  Lighting is nice and soft.  Good shot.', '2008-09-04 20:08:35.000000', NULL, 1),
(4935091, 717515, 33769, '<td valign="top">This is absolutely amazing (IT MUST be a blue)</td>', 'This is absolutely amazing (IT MUST be a blue)', '2008-09-04 21:30:44.000000', NULL, 1),
(4935201, 716755, 47316, '<td valign="top">lol! That''s pretty creepy actually! Nice lighting and take on a classic shot. Ahh! I kept thinking it looked weird... i think you used the wrong arm! Usually the thumb is towards the camera... seems like a nit pick but with the arm that and the angle the hand is at it almost appears like someone is holding the baby up behind their back...</td>', 'lol! That''s pretty creepy actually! Nice lighting and take on a classic shot. Ahh! I kept thinking it looked weird... i think you used the wrong arm! Usually the thumb is towards the camera... seems like a nit pick but with the arm that and the angle the hand is at it almost appears like someone is holding the baby up behind their back...', '2008-09-04 22:15:11.000000', NULL, 1),
(4935203, 717725, 47316, '<td valign="top">Colorful! Nice depth of field. I guess I''m not digging this challenge much because every shot I see I think "that would be great with a real person!" and yours is no exception.</td>', 'Colorful! Nice depth of field. I guess I''m not digging this challenge much because every shot I see I think "that would be great with a real person!" and yours is no exception.', '2008-09-04 22:16:16.000000', NULL, 1),
(4935207, 717699, 47316, '<td valign="top">nicely done! eerily appears when seen from the corner of my eye to be a portrait of a real person. I think the composition is a little cramped on the left side. I''m all for negative space in a shot like this but it just seems a little off balance.</td>', 'nicely done! eerily appears when seen from the corner of my eye to be a portrait of a real person. I think the composition is a little cramped on the left side. I''m all for negative space in a shot like this but it just seems a little off balance.', '2008-09-04 22:17:38.000000', NULL, 1),
(4935211, 717672, 47316, '<td valign="top">ok this isn''t just you I''ve been saying it to everyone... what a creepy challenge this is! So that aside ;) Nice shot. I like the soft colors, dof, tight crop, probably the best you would do given the subject matter.</td>', 'ok this isn''t just you I''ve been saying it to everyone... what a creepy challenge this is! So that aside ;) Nice shot. I like the soft colors, dof, tight crop, probably the best you would do given the subject matter.', '2008-09-04 22:19:09.000000', NULL, 1),
(4935213, 717732, 47316, '<td valign="top">Nice and simple. I like the composition. Something seems a little off to me with the coloring or something... perhaps a little overexposed or pale? Not sure... nice job though.</td>', 'Nice and simple. I like the composition. Something seems a little off to me with the coloring or something... perhaps a little overexposed or pale? Not sure... nice job though.', '2008-09-04 22:20:46.000000', NULL, 1),
(4935219, 717267, 47316, '<td valign="top">Ah! Wow. This just made me really nostalgic. I had those as a kid... aw now I want them back! Cool choice of doll but I think the point of how small they are could have gotten across in a more subtle and humorous way. I don''t think you quite nailed it.</td>', 'Ah! Wow. This just made me really nostalgic. I had those as a kid... aw now I want them back! Cool choice of doll but I think the point of how small they are could have gotten across in a more subtle and humorous way. I don''t think you quite nailed it.', '2008-09-04 22:24:16.000000', NULL, 1),
(4935224, 717364, 47316, '<td valign="top">what creepy dolls! nice lighting though I think you could have had a tad more on the faces, perhaps just a little bit of fill to offset the backlight. this shot has some nice textures.</td>', 'what creepy dolls! nice lighting though I think you could have had a tad more on the faces, perhaps just a little bit of fill to offset the backlight. this shot has some nice textures.', '2008-09-04 22:27:00.000000', NULL, 1),
(4935414, 714884, 95622, '<td valign="top">I love this picture.</td>', 'I love this picture.', '2008-09-05 00:18:34.000000', NULL, 1),
(4935808, 714884, 54566, '<td valign="top">is this lit frm above only - great lighting.</td>', 'is this lit frm above only - great lighting.', '2008-09-05 07:13:58.000000', NULL, 1),
(4935818, 716715, 54566, '<td valign="top">nice idea. but there appears to be a slight shake.</td>', 'nice idea. but there appears to be a slight shake.', '2008-09-05 07:18:39.000000', NULL, 1),
(4935826, 717608, 54566, '<td valign="top">wonder if u had another stringed puppet hand cutting the strings ... nice idea shot.</td>', 'wonder if u had another stringed puppet hand cutting the strings ... nice idea shot.', '2008-09-05 07:21:02.000000', NULL, 1),
(4936110, 717430, 33769, '<td valign="top">this is adorable and playful at the same time; I''m sure there are some clown phobias out there among the voters and your score may suffer for it- well you''re fortunate since I''m not one of them ;) - I think even the scary looking clowns are funny most of the time ;) :-) I like the sepia tone of this its warm and lets me imagine what the colors of the clowns outfit/hair would be  - it eliminates any distracting colors that would pull the eye in a million different directions and allows me to focus on he subject - :-) well done :-) high score</td>', 'this is adorable and playful at the same time; I''m sure there are some clown phobias out there among the voters and your score may suffer for it- well you''re fortunate since I''m not one of them ;) - I think even the scary looking clowns are funny most of the time ;) :-) I like the sepia tone of this its warm and lets me imagine what the colors of the clowns outfit/hair would be  - it eliminates any distracting colors that would pull the eye in a million different directions and allows me to focus on he subject - :-) well done :-) high score', '2008-09-05 11:03:49.000000', NULL, 1),
(4936114, 717501, 33769, '<td valign="top">interesting composition... i like the choice of high-contrast and darker grungy feel to the image it works :-)</td>', 'interesting composition... i like the choice of high-contrast and darker grungy feel to the image it works :-)', '2008-09-05 11:04:52.000000', NULL, 1),
(4936124, 717292, 33769, '<td valign="top">I''m not sure if this quite fits most peoples opinions of what a doll is :) but I like the out of box thinking and the image itself is amazingly done - the lighting is well done- I gave this a high score and hope it does well despite literal linear thinkers ;) models are the dolls of the fashion world- dressed up set on a stage  posed and prettied up and or starved until they''re nearly non-existent --its a sad reality - but a beautiful photograph -- <br/> <br/>my first reaction by the way was: -anorexia nervosa? then it took me a few moments to look over the image and the lighting and the pose...  -- all well done -- high score</td>', 'I''m not sure if this quite fits most peoples opinions of what a doll is :) but I like the out of box thinking and the image itself is amazingly done - the lighting is well done- I gave this a high score and hope it does well despite literal linear thinkers ;) models are the dolls of the fashion world- dressed up set on a stage  posed and prettied up and or starved until they''re nearly non-existent --its a sad reality - but a beautiful photograph --  my first reaction by the way was: -anorexia nervosa? then it took me a few moments to look over the image and the lighting and the pose...  -- all well done -- high score', '2008-09-05 11:12:10.000000', NULL, 1),
