(4944502, 717355, 83313, '<td valign="top">Excellent concept and execution! (pun intended)</td>', 'Excellent concept and execution! (pun intended)', '2008-09-09 14:31:04.000000', NULL, 1),
(4944525, 717671, 83313, '<td valign="top">A good basic shot. Well lit, great color and sharpness. Did anyone yet mention the stray thread on the neck? Yea, I knew I wasn''t the first to notice it, but that''s the only flaw I can see.</td>', 'A good basic shot. Well lit, great color and sharpness. Did anyone yet mention the stray thread on the neck? Yea, I knew I wasn''t the first to notice it, but that''s the only flaw I can see.', '2008-09-09 14:48:06.000000', NULL, 1),
